struct algorithm
{
    struct object     hdr;
    enum alg_id       id;
    enum chain_mode   chain_mode;
    ULONG             flags;
    enum ecc_curve_id curve_id;
};

enum chain_mode
{
    CHAIN_MODE_CBC,
    CHAIN_MODE_ECB,
    CHAIN_MODE_CFB,
    CHAIN_MODE_CCM,
    CHAIN_MODE_GCM,
};

struct dsa_key
{
    SYMCRYPT_DLKEY   *handle;
    SYMCRYPT_DLGROUP *group;
    UCHAR             seed[20];
    UINT32            count;
};

struct ecc_key
{
    SYMCRYPT_ECKEY   *handle;
    SYMCRYPT_ECURVE  *curve;
    enum ecc_curve_id curve_id;
};

struct gcm_key
{
    SYMCRYPT_GCM_EXPANDED_KEY handle;
    SYMCRYPT_GCM_STATE        state;
};

struct key
{
    struct object hdr;
    enum alg_id   alg_id;
    ULONG         flags;
    union
    {
        struct symmetric_key s;
        struct asymmetric_key a;
    };
};

static const struct
{
    const WCHAR *name;
    ULONG        class;
    ULONG        object_length;
    ULONG        hash_length;
    ULONG        hash_block_length;
    enum ecc_curve_id curve_id;
    enum chain_mode   chain_mode;
}

struct symmetric_key
{
    enum chain_mode  mode;
    ULONG            block_size;
    UCHAR           *secret;
    ULONG            secret_len;
    UCHAR            vector[BLOCK_LENGTH_AES];
    CRITICAL_SECTION cs;
    union
    {
        struct aes_key  aes;
        struct gcm_key  gcm;
        struct hkdf_key hkdf;
    };
};

union
{
    struct aes_key  aes;
    struct gcm_key  gcm;
    struct hkdf_key hkdf;
};

union
{
